function [rate, spin_z] = kpi_rates(w)
%KPI_RATES  The body rate's magnitude [deg/s] and the spin about +Z [deg/s] of the body rate w [rad/s].
%   w: real[1/s][3] (passed in 1/s)
%   returns rate: real[1/s] (passed in 1/s)
%   returns spin_z: real[1/s] (passed in 1/s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    rate = 0;
    spin_z = 0;
    rate = (asils.pc.norm_(w) * (180 / pi));
    spin_z = (w(3) * (180 / pi));
end
